"""Snap clock edges to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.models import Span
from hourglass.parsing import format_span

def check_step(step: int) -> None:
    """Steps must be whole numbers that divide an hour."""
    if not isinstance(step, int) or step <= 0 or 60 % step:
        raise ValueError(f"step must divide 60: {step!r}")

def snap_minutes(minutes: int, step: int) -> int:
    """Nearest multiple of step, halves rounding up."""
    return (minutes + step // 2) // step * step

def snap_span(span: Span, step: int) -> Span:
    snapped_start = snap_minutes(span.start, step)
    snapped_end = snap_minutes(span.end, step)
    return Span(snapped_start, snapped_end)

def format_duration(minutes: int) -> str:
    hours, rest = divmod(minutes, 60)
    return f"{hours}h {rest}m"

def label_span(span: Span) -> str:
    text = format_span(span)
    return f"{text} ({format_duration(span.minutes)})"

def round_span_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Snap each span to step and label the result."""
    check_step(step)
    snapped = (snap_span(span, step) for span in spans)
    return [label_span(span) for span in snapped]

