import unittest

from hourglass.parsing import parse_span
from hourglass.rounding import (
    check_step,
    round_span_labels,
    snap_minutes
)

class SnapTests(unittest.TestCase):
    def test_rounds_to_nearest(self):
        self.assertEqual(snap_minutes(544, 15), 540)
        self.assertEqual(snap_minutes(548, 15), 555)

    def test_halfway_rounds_up(self):
        self.assertEqual(snap_minutes(545, 10), 550)

class StepTests(unittest.TestCase):
    def test_divisors_of_an_hour_pass(self):
        steps = [1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30, 60]
        for step in steps:
            with self.subTest(step=step):
                check_step(step)

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120, 7.5, 15.0, "15"):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    check_step(step)

class LabelTests(unittest.TestCase):
    def test_label_shows_rounded_times_and_length(self):
        spans = [parse_span("09:04-17:16")]
        labels = round_span_labels(spans, 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_one_label_per_span_in_order(self):
        first = parse_span("08:02-12:31")
        second = parse_span("13:00-17:44")
        labels = round_span_labels([first, second], 15)
        expected = [
            "08:00-12:30 (4h 30m)",
            "13:00-17:45 (4h 45m)"
        ]
        self.assertEqual(labels, expected)

    def test_halfway_edges_round_up(self):
        spans = [parse_span("09:05-09:25")]
        labels = round_span_labels(spans, 10)
        self.assertEqual(labels, ["09:10-09:30 (0h 20m)"])

    def test_end_of_day_is_kept(self):
        spans = [parse_span("23:50-24:00")]
        labels = round_span_labels(spans, 15)
        self.assertEqual(labels, ["23:45-24:00 (0h 15m)"])

    def test_no_spans_gives_no_labels(self):
        self.assertEqual(round_span_labels([], 15), [])

    def test_bad_step_is_refused_up_front(self):
        for step in (0, -5, 7):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_span_labels([], step)

    def test_span_that_rounds_to_nothing_raises(self):
        spans = [parse_span("09:01-09:04")]
        with self.assertRaises(ValueError):
            round_span_labels(spans, 15)
